const rawOutput = $json.output;

try {
  const cleanedOutput = rawOutput
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  const meeting = JSON.parse(cleanedOutput);

  return [
    {
      json: {
        meetingTitle: meeting.meetingTitle,
        summary: meeting.summary,
        decisions: Array.isArray(meeting.decisions)
          ? meeting.decisions
          : [],
        actionItems: Array.isArray(meeting.actionItems)
          ? meeting.actionItems
          : [],
        unresolvedQuestions: Array.isArray(meeting.unresolvedQuestions)
          ? meeting.unresolvedQuestions
          : [],
        followUpSubject: meeting.followUpSubject,
        followUpEmail: meeting.followUpEmail,
      },
    },
  ];
} catch (error) {
  throw new Error(`Could not parse the meeting analysis: ${error.message}`);
}

const meeting = $json;
const actionItems = Array.isArray(meeting.actionItems)
  ? meeting.actionItems
  : [];

return actionItems.map(item => ({
  json: {
    timestamp: new Date().toISOString(),
    meetingTitle: meeting.meetingTitle,
    task: item.task || '',
    owner: item.owner || 'Unassigned',
    deadline: item.deadline || 'Not specified',
    status: item.status || 'Open',
  },
}));
